using namespace std;

long long get(int x) {
    return x * 1ll * (x + 1) / 2;
}

int main() {
#ifdef _DEBUG
    freopen("input.txt", "r", stdin);
//  freopen("output.txt", "w", stdout);
#endif

    int t;
    cin >> t;
    while (t--) {
        int k;
        long long x;
        cin >> k >> x;
        long long l = 1, r = 2 * k - 1;
        long long res = 2 * k - 1;
        bool over = false;
        while (l <= r) {
            int mid = (l + r) >> 1;
            if (mid >= k) {
                over = (get(k) + get(k - 1) - get(2 * k - 1 - mid) >= x);
            } else {
                over = (get(mid) >= x);
            }
            if (over) {
                res = mid;
                r = mid - 1;
            } else {
                l = mid + 1;
            }
        }
        cout << res << endl;
    }

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

bool get(long long a, long long b, long long x) {
    if (a == x || b == x) return true;
    if (a < b) swap(a, b);
    if (b > a - b) b = a - b;
    if (x > max(a, b) || a == 0 || b == 0) return false;
    long long cnt = max(1ll, (a - max(x, b)) / (2 * b));
    return get(a - b * cnt, b, x);
}

int main() {
#ifdef _DEBUG
    freopen("input.txt", "r", stdin);
//  freopen("output.txt", "w", stdout);
#endif

    int t;
    cin >> t;
    while (t--) {
        long long a, b, x;
        cin >> a >> b >> x;
        if (get(a, b, x)) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
    }

    return 0;
}

#include <bits/stdc++.h>     

using namespace std;

const int N = 200043;
const int K = 20;
vector<int> idx[N];
int m[N], k[N];

bool frac_greater(pair<int, int> a, pair<int, int> b)
{
    return a.first * b.second > a.second * b.first;
}

int main()
{
    int n;
    scanf("%d", &n);
    for(int i = 0; i < n; i++)
    {
        scanf("%d %d", &m[i], &k[i]);
        idx[m[i]].push_back(i);
    }

    vector<int> cert;
    pair<int, int> ans = {0, 1};
    for(int i = 1; i <= K; i++)
    {
        vector<int> score(N);
        for(int j = 0; j < n; j++)
            score[m[j]] += min(i, k[j]);
        vector<pair<int, int>> aux;
        for(int j = 0; j < N; j++)
            aux.push_back(make_pair(score[j], j));
        sort(aux.rbegin(), aux.rend());
        pair<int, int> cur_ans = {0, i};
        vector<int> cur_cert;
        for(int j = 0; j < i; j++)
        {
            cur_ans.first += aux[j].first;
            cur_cert.push_back(aux[j].second);
        }
        if(frac_greater(cur_ans, ans))
        {
            ans = cur_ans;
            cert = cur_cert;
        }
    }
    cout << cert.size() << endl;
    shuffle(cert.begin(), cert.end(), mt19937(time(NULL)));
    for(auto x : cert) cout << x << " ";
    cout << endl;
}

